async function main(): Promise<void> {
  const columns = [
    'id',
    'title',
    'startYear',
    'startMonth',
    'startDay',
    'endYear',
    'precision',
    'salience',
    'importance',
    'regions',
    'subjects',
    'summary',
    'body',
    'sources',
    'image',
    'salienceByRegion',
  ]
  const ids = new Set<string>()
  const rows = events.map((e) => {
    if (ids.has(e.id)) throw new Error(`duplicate ${e.id}`)
    ids.add(e.id)
    return {
      id: e.id,
      title: e.title,
      startYear: e.start,
      startMonth: e.month != null ? String(e.month) : '',
      startDay: e.day != null ? String(e.day) : '',
      endYear: e.end ?? '',
      precision: e.precision,
      salience: String(e.salience),
      importance: String(e.importance),
      regions: e.regions,
      subjects: e.subjects,
      summary: e.summary,
      body: e.body,
      sources: e.sources,
      image: '',
      salienceByRegion: e.sbr ?? '',
    }
  })
  if (rows.length < 120) throw new Error(`only ${rows.length} events`)
  await mkdir(join(root, 'data', 'source'), { recursive: true })
  await writeFile(join(root, 'data', 'source', 'events.csv'), stringifyCsv(rows, columns), 'utf8')
  console.log(`wrote ${rows.length} seed events`)
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})
